// Smaller companies rarely post to the Bundesagentur, but many are on OpenStreetMap as
// office=it WITH their website - which the resolver can read directly, no guessing.
// Measured earlier: ~209 in Berlin and ~161 in München. Weekly, one Overpass query per area,
// sequential: Overpass is a shared free service and rate-limits bursts.
// OSM is skipped for Amsterdam on purpose: measured, 91 POIs, one recognisable tech employer.
const cfg = $('Config').first().json;
const H = (typeof helpers !== 'undefined' && helpers.httpRequest) ? helpers : (this && this.helpers);
const due = cfg.osmSeedNow === true || new Date().getDay() === Number(cfg.osmSeedWeekday ?? 1);
if (!due) return [{ json: { rows: [], areas: 'not due' } }];

const AREAS = {   // south, west, north, east
  berlin:    { region: 'berlin', bbox: '52.34,13.09,52.68,13.76' },
  muenchen:  { region: 'bayern', bbox: '48.06,11.36,48.25,11.72' },
  nuernberg: { region: 'bayern', bbox: '49.35,10.85,49.65,11.20' },   // incl. Fürth, Erlangen
};
const want = new Set(cfg.regions || []);
const endpoint = cfg.overpassUrl || 'https://overpass-api.de/api/interpreter';
const proxy = cfg.discoveryProxy || '';
const norm = s => String(s || '').toLowerCase().replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const LEGAL = /\b(gmbh|mbh|ag|se|kg|kgaa|co|ug|ohg|e v|ev|b v|bv|n v|nv|inc|llc|ltd|limited|plc|corp|corporation|sa|sas|sarl|srl|spa|holding|group|gruppe|deutschland|germany|netherlands|nederland|europe)\b/g;
const coKey = s => norm(s).replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || norm(s);
const rows = new Map();
const areas = {};
// n8n kills a Code node after 5 minutes; stop starting new queries well before that.
const deadline = Date.now() + 200000;
for (const [key, a] of Object.entries(AREAS)) {
  if (!want.has(a.region) || !(cfg.osmAreas || Object.keys(AREAS)).includes(key)) continue;
  if (Date.now() > deadline) { areas[key] = 'skipped (time budget)'; continue; }
  const q = `[out:json][timeout:60];nwr["office"~"^(it|software)$"]["name"]["website"](${a.bbox});out tags center;`;
  const url = endpoint + '?data=' + encodeURIComponent(q);
  // Overpass rate-limits back-to-back queries from one address (seen live: the 2nd and 3rd area
  // came back empty with a 2 s gap). Space them out and retry with backoff.
  let got = null;
  for (let attempt = 0; attempt < 3 && !got && Date.now() < deadline; attempt++) {
    if (attempt) await new Promise(res => setTimeout(res, 15000 * attempt));
    try {
      const r = await H.httpRequest({ method: 'GET', url: proxy ? proxy + '?u=' + encodeURIComponent(url) : url,
        headers: { 'User-Agent': 'job-automation/1.0 (personal job search; weekly)' },
        timeout: Math.max(5000, Math.min(60000, deadline - Date.now())),
        returnFullResponse: true, ignoreHttpStatusErrors: true, json: false });
      if (r.statusCode === 200) got = typeof r.body === 'string' ? JSON.parse(r.body) : r.body;
    } catch (e) { /* retried below */ }
  }
  let n = 0;
  for (const e of (got && got.elements) || []) {
    const t = e.tags || {};
    const site = t.website || t['contact:website'];
    if (!t.name || !site) continue;
    const k = coKey(t.name);                                  // same key as the ad-sourced candidates
    if (k && !rows.has(k)) { rows.set(k, { name: String(t.name).trim(), norm_name: k, website: site,
                                           regions: [a.region], sources: ['osm'] }); n++; }
  }
  areas[key] = got ? n : 'failed';
  await new Promise(res => setTimeout(res, 5000));
}
return [{ json: { rows: [...rows.values()], areas } }];

// Layer 3: turn employer NAMES (seen in Bundesagentur / Adzuna / Arbeitnow ads) into readable
// careers feeds. Two routes, cheapest first:
//   1. guess the board name on keyless ATS APIs (Greenhouse, Lever, Ashby, SmartRecruiters,
//      Personio, Recruitee) - accepted only with jobs in our regions AND a matching company name
//   2. guess the company's domain, confirm it by the page title, find the careers page and
//      detect the system behind it (Workday, SuccessFactors, or any of the above)
// Ad links are no help: measured 2026-09-24, 19% of Bundesagentur ads carry one and every
// one pointed at an aggregator (gute-jobs.de, jobexport.de, get-in-it.de), never the employer.
const cfg = $('Config').first().json;
const H = (typeof helpers !== 'undefined' && helpers.httpRequest) ? helpers : (this && this.helpers);
const proxy = cfg.discoveryProxy || '';            // tests only: route every request via a mock
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126 Safari/537.36';

async function fetchRaw(url, { method = 'GET', body, accept = '*/*', timeout = 8000 } = {}) {
  try {
    const r = await H.httpRequest({
      method, url: proxy ? proxy + '?u=' + encodeURIComponent(url) : url,
      headers: { 'User-Agent': UA, Accept: accept, 'Accept-Language': 'de,en;q=0.8,nl;q=0.6',
                 ...(body ? { 'Content-Type': 'application/json' } : {}) },
      body: body ? JSON.stringify(body) : undefined,
      timeout, returnFullResponse: true, ignoreHttpStatusErrors: true, json: false });
    let b = r.body;
    if (b && typeof b === 'object' && !(typeof Buffer !== 'undefined' && Buffer.isBuffer(b))) b = JSON.stringify(b);
    return { status: r.statusCode, text: String(b == null ? '' : b) };
  } catch (e) {
    return { status: 0, text: '' };
  }
}
async function fetchJson(url, opts) {
  const r = await fetchRaw(url, { accept: 'application/json', ...opts });
  if (r.status !== 200) return null;
  try { return JSON.parse(r.text); } catch (e) { return null; }
}

// --- names -------------------------------------------------------------------------------
const norm = s => String(s || '').toLowerCase().replace(/ß/g, 'ss')
  .normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
const LEGAL = /\b(gmbh|mbh|ag|se|kg|kgaa|co|ug|ohg|e v|ev|b v|bv|n v|nv|inc|llc|ltd|limited|plc|corp|corporation|sa|sas|sarl|srl|spa|holding|group|gruppe|deutschland|germany|netherlands|nederland|europe)\b/g;
const coKey = s => norm(s).replace(LEGAL, ' ').replace(/\s+/g, ' ').trim() || norm(s);
const GENERIC = new Set(['digital', 'software', 'solutions', 'systems', 'system', 'consulting', 'services',
  'service', 'tech', 'technology', 'technologies', 'data', 'it', 'media', 'bank', 'energy', 'engineering',
  'management', 'partner', 'partners', 'international', 'global', 'the', 'und', 'and', 'of', 'de', 'ki',
  'ai', 'innovation', 'innovations', 'labs', 'lab', 'studio', 'company', 'agentur', 'beratung', 'netz',
  'informatik', 'network', 'networks', 'cloud', 'online', 'smart', 'mobile', 'web', 'health', 'medical']);
const tokens = s => coKey(s).split(' ').filter(t => t.length >= 3 && !GENERIC.has(t));
const nameMatch = (a, b) => { const B = new Set(tokens(b)); return tokens(a).some(t => B.has(t)); };
function slugsFor(name) {
  const w = coKey(name).split(' ').filter(Boolean);
  const out = [w.join(''), w.join('-')];
  if (w.length > 1 && w[0].length >= 5 && !GENERIC.has(w[0])) out.push(w[0]);
  return [...new Set(out)].filter(s => s.length >= 3).slice(0, 3);
}

// --- regions ------------------------------------------------------------------------------
const RX = {
  berlin:    /\bberlin\b/i,
  bayern:    /\b(m[uü]nchen|munich|n[uü]rnberg|nuremberg|bayern|bavaria|augsburg|erlangen|f[uü]rth|herzogenaurach|forchheim|ingolstadt|regensburg|w[uü]rzburg|bamberg|garching|unterf[oö]hring|unterschlei[sß]heim|ismaning)\b/i,
  amsterdam: /\b(amsterdam|amstelveen|diemen|schiphol|utrecht|haarlem|hoofddorp|leiden|delft|hilversum|almere|netherlands|nederland|den haag|the hague|rotterdam|eindhoven)\b/i
};
const want = cfg.regions || ['berlin', 'bayern', 'amsterdam'];
const inRegion = locs => locs.filter(l => want.some(r => RX[r].test(l || ''))).length;
const COUNTRY = { berlin: 'de', bayern: 'de', amsterdam: 'nl' };

// --- route 1: keyless ATS APIs, by board-name guess ---------------------------------------
const PROBES = {
  async greenhouse(s) {
    const d = await fetchJson(`https://boards-api.greenhouse.io/v1/boards/${s}/jobs`);
    if (!d || !Array.isArray(d.jobs) || !d.jobs.length) return null;
    const b = await fetchJson(`https://boards-api.greenhouse.io/v1/boards/${s}`);
    return { total: d.jobs.length, local: inRegion(d.jobs.map(j => (j.location || {}).name)), boardName: (b || {}).name || '' };
  },
  async lever(s) {
    const d = await fetchJson(`https://api.lever.co/v0/postings/${s}?mode=json`);
    if (!Array.isArray(d) || !d.length) return null;
    return { total: d.length, local: inRegion(d.map(j => (j.categories || {}).location)), boardName: '' };
  },
  async ashby(s) {
    const d = await fetchJson(`https://api.ashbyhq.com/posting-api/job-board/${s}`);
    if (!d || !Array.isArray(d.jobs) || !d.jobs.length) return null;
    return { total: d.jobs.length, local: inRegion(d.jobs.map(j => j.location)), boardName: '' };
  },
  async smartrecruiters(s, countries) {
    let total = 0, name = '';
    for (const c of countries) {
      const d = await fetchJson(`https://api.smartrecruiters.com/v1/companies/${s}/postings?limit=100&country=${c}`);
      if (!d || !Array.isArray(d.content)) continue;
      total += d.totalFound || d.content.length;
      name = name || ((d.content[0] || {}).company || {}).name || '';
    }
    return total ? { total, local: total, boardName: name } : null;     // country-filtered server-side
  },
  async personio(s) {
    let r = await fetchRaw(`https://${s}.jobs.personio.de/xml`);
    if (r.status !== 200 || !r.text.includes('<position>')) r = await fetchRaw(`https://${s}.jobs.personio.com/xml`);
    if (r.status !== 200 || !r.text.includes('<position>')) return null;
    // count positions, not offices: one job with three offices is still one job
    const pos = r.text.match(/<position>[\s\S]*?<\/position>/g) || [];
    const sub = (r.text.match(/<subcompany>([^<]*)<\/subcompany>/) || [])[1] || '';
    return { total: pos.length, boardName: sub,
             local: inRegion(pos.map(p => (p.match(/<office>[^<]*<\/office>/g) || []).join(' '))) };
  },
  async recruitee(s) {
    const d = await fetchJson(`https://${s}.recruitee.com/api/offers/`);
    if (!d || !Array.isArray(d.offers) || !d.offers.length) return null;
    return { total: d.offers.length, local: inRegion(d.offers.map(o => [o.city, o.location, o.country].join(' '))),
             boardName: (d.offers[0] || {}).company_name || '' };
  },
};

async function viaAtsGuess(name, countries) {
  const slugs = slugsFor(name), full = slugs[0];
  const tries = [];
  for (const s of slugs) for (const [ats, probe] of Object.entries(PROBES)) tries.push({ s, ats, p: probe(s, countries) });
  const results = await Promise.all(tries.map(async t => ({ ...t, r: await t.p })));
  for (const t of results) {
    if (!t.r || !t.r.local) continue;
    // Board names like "digital" are shared by many companies: demand a name match, or the
    // full-name slug on systems that don't expose a company name at all.
    const ok = t.r.boardName ? nameMatch(name, t.r.boardName) : t.s === full;
    if (ok) return { ats: t.ats, token: t.s, total: t.r.total, local: t.r.local, via: 'ats-guess' };
  }
  return null;
}

// --- route 2: the company's own site ------------------------------------------------------
// No URL class in the Code-node sandbox (only Buffer, timers, btoa/atob, TextEncoder...).
const hostOf = u => (String(u).match(/^https?:\/\/([^/:?#]+)/i) || [])[1] || '';
const absUrl = (h, base) => /^https?:\/\//i.test(h) ? h : h.startsWith('//') ? 'https:' + h
  : h.startsWith('/') ? (base.match(/^https?:\/\/[^/]+/) || [''])[0] + h : base.replace(/[^/]*$/, '') + h;
const CAREER_HREF = /href="([^"#]*?(?:karriere|career|jobs|stellen|vacatures|werken-bij|join)[^"#]*)"/gi;
async function detectOnPage(html, pageUrl) {
  let m;
  if ((m = html.match(/https:\/\/([\w-]+)\.(wd\d+)\.myworkdayjobs\.com\/(?:[a-z]{2}-[A-Z]{2}\/)?([\w-]+)/)))
    return { ats: 'workday', token: `${m[1]}|${m[2]}|${m[3]}` };
  // the same system on its other domain: wd3.myworkdaysite.com/recruiting/<tenant>/<site>
  if ((m = html.match(/https:\/\/(wd\d+)\.myworkdaysite\.com\/(?:[a-z]{2}-[A-Z]{2}\/)?recruiting\/([\w-]+)\/([\w-]+)/)))
    return { ats: 'workday', token: `${m[2]}|${m[1]}|${m[3]}` };
  if ((m = html.match(/([\w-]+)\.jobs\.personio\.(?:de|com)/))) return { ats: 'personio', token: m[1] };
  if ((m = html.match(/(?:boards|job-boards)\.greenhouse\.io\/(?:embed\/job_board\?for=)?([\w-]+)/))) return { ats: 'greenhouse', token: m[1] };
  if ((m = html.match(/jobs\.lever\.co\/([\w-]+)/))) return { ats: 'lever', token: m[1] };
  if ((m = html.match(/jobs\.ashbyhq\.com\/([\w-]+)/))) return { ats: 'ashby', token: m[1] };
  if ((m = html.match(/(?:jobs|careers)\.smartrecruiters\.com\/([\w-]+)/))) return { ats: 'smartrecruiters', token: m[1] };
  if ((m = html.match(/https?:\/\/([\w-]+)\.recruitee\.com/))) return { ats: 'recruitee', token: m[1] };
  // SuccessFactors career sites live on their own host (jobs.x.com, careers.x.de): try its RSS.
  const hosts = new Set([...html.matchAll(/https:\/\/((?:jobs|careers|karriere)\.[\w.-]+\.(?:com|de|nl|eu))/g)].map(x => x[1]));
  const h0 = hostOf(pageUrl); if (/^(jobs|careers|karriere)\./.test(h0)) hosts.add(h0);
  for (const h of [...hosts].slice(0, 3)) {
    const r = await fetchRaw(`https://${h}/services/rss/job/?locale=de_DE&keywords=a`);
    if (r.status === 200 && r.text.includes('<item>')) return { ats: 'successfactors', token: `https://${h}` };
  }
  return null;
}
async function verify(found, countries) {
  if (found.ats === 'workday') {
    const [t, w, s] = found.token.split('|');
    const d = await fetchJson(`https://${t}.${w}.myworkdayjobs.com/wday/cxs/${t}/${s}/jobs`,
      { method: 'POST', body: { appliedFacets: {}, limit: 1, offset: 0, searchText: '' } });
    return d && d.total ? { total: d.total, local: null } : null;
  }
  if (found.ats === 'successfactors') return { total: 1, local: null };      // RSS already checked
  const r = await PROBES[found.ats](found.token, countries);
  return r && r.total ? { total: r.total, local: r.local } : null;
}
// Scan a confirmed company site: its home page plus up to three careers pages it links to.
async function scanSite(home, homeHtml, countries) {
  const pages = [[home, homeHtml]];
  const links = [...homeHtml.matchAll(CAREER_HREF)].map(x => absUrl(x[1].replace(/&amp;/g, '&'), home))
    .filter(u => /^https?:/.test(u));
  for (const u of [...new Set(links)].slice(0, 3)) {
    const p = await fetchRaw(u, { timeout: 7000 });
    if (p.status === 200) pages.push([u, p.text]);
  }
  for (const [u, html] of pages) {
    const found = await detectOnPage(html, u);
    if (!found) continue;
    const v = await verify(found, countries);
    if (v) return { ...found, total: v.total, local: v.local, via: 'website ' + home };
  }
  return { none: true, via: 'website ' + home };                  // right company, unreadable system
}
// Name only: guess the domain, and accept it only if the page title names the company.
async function viaWebsite(name, countries) {
  const slugs = slugsFor(name).slice(0, 2);
  const tlds = countries.includes('nl') ? ['nl', 'com'] : ['de', 'com'];
  const want = tokens(name);
  if (!want.length) return null;
  for (const s of slugs) for (const tld of tlds) {
    const home = `https://www.${s}.${tld}`;
    const r = await fetchRaw(home, { timeout: 7000 });
    if (r.status !== 200 || r.text.length < 500) continue;
    const title = norm(((r.text.match(/<title[^>]*>([^<]*)</i) || [])[1] || '') + ' ' +
                       ((r.text.match(/og:site_name"\s+content="([^"]*)"/i) || [])[1] || ''));
    if (!want.some(t => title.includes(t))) continue;              // a parked or unrelated domain
    return scanSite(home, r.text, countries);
  }
  return null;
}
// Website already known (OpenStreetMap lists it): no guessing, no title check needed.
async function viaKnownSite(website, countries) {
  let home = String(website).trim();
  if (!/^https?:\/\//i.test(home)) home = 'https://' + home.replace(/^\/+/, '');
  const r = await fetchRaw(home, { timeout: 8000 });
  if (r.status !== 200 || r.text.length < 300) return null;
  return scanSite(home, r.text, countries);
}

// --- run ----------------------------------------------------------------------------------
const known = new Set($('Load Employers').all().map(i => coKey((i.json || {}).name)).filter(Boolean));
const cands = $('Load Candidates').all().map(i => i.json).filter(c => c && c.id && c.name);
async function resolve(c) {
  const regions = (Array.isArray(c.regions) ? c.regions : String(c.regions || '').replace(/[{}]/g, '').split(','))
    .filter(r => want.includes(r));
  const countries = [...new Set(regions.map(r => COUNTRY[r]).filter(Boolean))];
  const cc = countries.length ? countries : ['de'];
  if (known.has(coKey(c.name))) return { ...c, status: 'skipped', note: 'already watched' };
  // A known website is the most precise route: small companies link their Personio or
  // Greenhouse board right there.
  if (c.website) {
    const k = await viaKnownSite(c.website, cc);
    if (k && !k.none) return { ...c, status: 'found', ...k, regions };
    const a = tokens(c.name).length ? await viaAtsGuess(c.name, cc) : null;
    if (a) return { ...c, status: 'found', ...a, regions };
    return { ...c, status: 'not_found', note: k ? 'site found, no readable job system (' + k.via + ')' : 'website did not load' };
  }
  if (!tokens(c.name).length) return { ...c, status: 'not_found', note: 'name too generic to guess' };
  const a = await viaAtsGuess(c.name, cc);
  if (a) return { ...c, status: 'found', ...a, regions };
  const w = await viaWebsite(c.name, cc);
  if (w && !w.none) return { ...c, status: 'found', ...w, regions };
  return { ...c, status: 'not_found', note: w ? 'site found, no readable job system (' + w.via + ')' : 'no board or site found' };
}
// A few companies at a time: each fans out to ~20 requests, and the Code node has 5 minutes.
// n8n kills a Code node after 5 minutes: stop starting new companies after 3.5. The rest stay
// 'new' in the database and simply come up again on the next run.
const deadline = Date.now() + 210000;
const out = [];
const par = Math.max(1, Number(cfg.discoverParallel) || 4);
for (let i = 0; i < cands.length && Date.now() < deadline; i += par) {
  out.push(...await Promise.all(cands.slice(i, i + par).map(resolve)));
}
return out.map(json => ({ json }));

// One item for the SQL below: Postgres runs a query once per input item.
const rows = $input.all().map(i => i.json).filter(r => r && r.id).map(r => ({
  id: r.id, name: r.name, status: r.status, ats: r.ats || null, token: r.token || null,
  regions: r.regions || [], note: (r.note || r.via || '').slice(0, 300) || null }));
return rows.length ? [{ json: { rows } }] : [];

const cfg = $('Config').first().json;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = new Date().toISOString().slice(0, 10);
const res = $('Resolve Employers').all().map(i => i.json);
const out = $input.all().map(i => i.json || {});
const saveError = out.some(r => r.error);
const inserted = out.filter(r => r.ats);
const found = res.filter(r => r.status === 'found');
// Weekly OpenStreetMap refresh: per-area counts, so a failing area is visible, not silent.
const areas = (($('Seed From OSM').first() || {}).json || {}).areas;
const osmFailed = areas && typeof areas === 'object' && Object.values(areas).some(v => typeof v !== 'number');
const osmLine = areas && typeof areas === 'object'
  ? '<p style="color:#666;">OpenStreetMap refresh: ' + esc(Object.entries(areas).map(([k, v]) => k + ' ' + v).join(', ')) + '</p>' : '';
// Mail only when there is something to look at.
if (!found.length && !saveError && !osmFailed) return [];
const count = s => res.filter(r => r.status === s).length;
const rows = found.map(r => '<tr><td>' + esc(r.name) + '</td><td>' + esc(r.ats) + '</td><td><code>'
  + esc(r.token) + '</code></td><td>' + esc((r.regions || []).join(', ')) + '</td><td>'
  + esc(r.local == null ? '?' : r.local) + ' / ' + esc(r.total) + '</td><td style="color:#888;">'
  + esc(r.via) + '</td></tr>').join('');
const html = `<div style="font:14px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;max-width:820px;margin:auto;">
  <h2 style="margin:0 0 4px;">Employer discovery - ${day}</h2>
  <p style="color:#666;">${res.length} checked &middot; ${found.length} found &middot; ${count('not_found')} not found
    &middot; ${count('skipped')} already watched</p>
  ${osmLine}${saveError ? '<div style="background:#ffe8e8;border:1px solid #e88;padding:10px;border-radius:6px;">'
    + '<b>Saving failed</b> - nothing was added to the watchlist. Check the Postgres credential.</div>' : ''}
  <table style="border-collapse:collapse;font-size:13px;" cellpadding="6" border="1">
    <tr style="background:#f4f4f4;"><th>Employer</th><th>System</th><th>Token</th><th>Regions</th>
      <th>Jobs in region / total</th><th>How found</th></tr>${rows}</table>
  <p style="color:#888;font-size:12px;">${inserted.length} added to <code>employers</code>; tomorrow's job run
    reads them. Wrong match? <code>UPDATE employers SET active = false WHERE name = '...';</code></p></div>`;
return [{ json: { subject: `[Discovery] ${inserted.length} new employer(s) watched - ${day}`, html } }];
